& !G \liff \lnot \OProv(\gn{!G}) \ollabel{G2-1}\ & \qquad	ext{$!G$ is a G"odel sentence}
otag \ & !G \lif \lnot \OProv(\gn{!G}) \ollabel{G2-2}\ & \qquad	ext{from \olref{G2-1}} 
otag\ & !G \lif (\OProv(\gn{!G}) \lif \lfalse) \ollabel{G2-3}\ & \qquad	ext{from \olref{G2-2} by logic}
otag\ & \OProv(\gn{ !G \lif (\OProv(\gn{!G}) \lif \lfalse) }) \ollabel{G2-4}\ & \qquad	ext{by from \olref{G2-3} by condition P1} 
otag\ & \OProv(\gn{!G}) \lif \OProv(\gn{ (\OProv(\gn{!G}) \lif \lfalse) }) \ollabel{G2-5}\ & \qquad	ext{from \olref{G2-4} by condition P2} 
otag\ & \OProv(\gn{!G}) \lif (\OProv(\gn{\OProv(\gn{!G})}) \lif \OProv(\gn{\lfalse})) \ollabel{G2-6}\ & \qquad	ext{from \olref{G2-5} by condition P2 and logic} 
otag\ & \OProv(\gn{!G}) \lif \OProv(\gn{\OProv(\gn{!G})}) \ollabel{G2-7}\ & \qquad	ext{by P3} 
otag\ & \OProv(\gn{!G}) \lif \OProv(\gn{\lfalse}) \ollabel{G2-8}\ & \qquad 	ext{from \olref{G2-6} and \olref{G2-7} by logic}
otag\ & \OCon \lif \lnot \OProv(\gn{!G}) \ollabel{G2-9}\ & \qquad	ext{contraposition of \olref{G2-8} and $\OCon \ident \lnot \OProv(\gn{\lfalse})$}
otag \ & \OCon \lif !G 
otag\ & \qquad	ext{from \olref{G2-1} and \olref{G2-9} by logic}
otag

& !D \liff (\OProv[\Th{T}](\gn{!D}) \lif !A) \ollabel{L-1}\ & \qquad 	ext{$!D$ is a fixed point of~$!B(y)$}
otag \ & !D \lif (\OProv[\Th{T}](\gn{!D}) \lif !A) \ollabel{L-2}\ & \qquad	ext{from \olref{L-1}}
otag\ & \OProv[\Th{T}](\gn{!D \lif (\OProv[\Th{T}](\gn{!D}) \lif !A)}) \ollabel{L-3}\ & \qquad 	ext{from \olref{L-2} by condition P1}
otag \ & \OProv[\Th{T}](\gn{!D}) \lif \OProv[\Th{T}](\gn{\OProv[\Th{T}](\gn{!D}) \lif !A}) \ollabel{L-4}\ &\qquad 	ext{from \olref{L-3} using condition P2}
otag \ & \OProv[\Th{T}](\gn{!D}) \lif (\OProv[\Th{T}](\gn{\OProv[\Th{T}](\gn{!D})}) \lif \OProv[\Th{T}](\gn{!A})) \ollabel{L-5}\ &\qquad 	ext{from \olref{L-4} using P2 again} 
otag\ & \OProv[\Th{T}](\gn{!D}) \lif \OProv[\Th{T}](\gn{\OProv[\Th{T}](\gn{!D})}) \ollabel{L-6}\ & \qquad	ext{by !!{derivability} condition P3} 
otag\ & \OProv[\Th{T}](\gn{!D}) \lif \OProv[\Th{T}](\gn{!A}) \ollabel{L-7} \ &\qquad	ext{from \olref{L-5} and \olref{L-6}}
otag\ & \OProv[\Th{T}](\gn{!A}) \lif !A \ollabel{L-8}\ &\qquad	ext{by assumption of the theorem} 
otag\ & \OProv[\Th{T}](\gn{!D}) \lif !A \ollabel{L-9}\ &\qquad	ext{from \olref{L-7} and \olref{L-8}}
otag\ & (\OProv[\Th{T}](\gn{!D}) \lif !A) \lif !D \ollabel{L-10}\ & \qquad 	ext{from \olref{L-1}}
otag \ & !D \ollabel{L-11}\ & \qquad	ext{from \olref{L-9} and \olref{L-10}}
otag \ & \OProv[\Th{T}](\gn{!D}) \ollabel{L-12}\ & \qquad	ext{from \olref{L-11} by condition~P1}
otag \ & !A \qquad\qquad	ext{from \olref{L-8} and \olref{L-12}}
otag
